INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7440410, 1176313, 103142, '<td valign="top">Whoot!! Now I can say congrats! Haunting, creepy image with a lot to say. I think the main problem is most people seeking praise because they don''t love themselves. So we seek it constantly from others. Or probably -- the biggest problem is we think too much of ourselves: whether we loathe ourselves or love ourselves, really, it shouldn''t be about us. Should it?</td>', 'Whoot!! Now I can say congrats! Haunting, creepy image with a lot to say. I think the main problem is most people seeking praise because they don''t love themselves. So we seek it constantly from others. Or probably -- the biggest problem is we think too much of ourselves: whether we loathe ourselves or love ourselves, really, it shouldn''t be about us. Should it?', '2016-03-01 22:14:40.000000', NULL, 0),
